def hex_to_rgba(value, alpha=0.16):
    value=value.strip('#')
    if len(value)==3:value=''.join(ch*2 for ch in value)
    r=int(value[0:2],16);g=int(value[2:4],16);b=int(value[4:6],16)
    return f'rgba({r}, {g}, {b}, {alpha})'
